package main

import (
	"encoding/json"
	"net/http"
	"github.com/graphql-go/graphql"
)

type User struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var users []User
var nextID = 1

var userType = graphql.NewObject(graphql.ObjectConfig{
	Name: "User",
	Fields: graphql.Fields{
		"id": &graphql.Field{Type: graphql.Int},
		"name": &graphql.Field{Type: graphql.String},
		"email": &graphql.Field{Type: graphql.String},
	},
})

var mutationType = graphql.NewObject(graphql.ObjectConfig{
	Name: "Mutation",
	Fields: graphql.Fields{
		"createUser": &graphql.Field{
			Type: userType,
			Args: graphql.FieldConfigArgument{
				"name": &graphql.ArgumentConfig{Type: graphql.NewNonNull(graphql.String)},
				"email": &graphql.ArgumentConfig{Type: graphql.NewNonNull(graphql.String)},
			},
			Resolve: func(p graphql.ResolveParams) (interface{}, error) {
				name, _ := p.Args["name"].(string)
				email, _ := p.Args["email"].(string)
				user := User{ID: nextID, Name: name, Email: email}
				nextID++
				users = append(users, user)
				return user, nil
			},
		},
	},
})

var queryType = graphql.NewObject(graphql.ObjectConfig{
	Name: "Query",
	Fields: graphql.Fields{
		"users": &graphql.Field{Type: graphql.NewList(userType), Resolve: func(p graphql.ResolveParams) (interface{}, error) { return users, nil }},
	},
})

var schema, _ = graphql.NewSchema(graphql.SchemaConfig{Query: queryType, Mutation: mutationType})

func main() {
	http.HandleFunc("/graphql", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		var params struct{ Query string `json:"query"` }
		json.NewDecoder(r.Body).Decode(&params)
		result := graphql.Do(graphql.Params{Schema: schema, RequestString: params.Query})
		json.NewEncoder(w).Encode(result)
	})
	http.ListenAndServe(":3000", nil)
}

