from fastapi import FastAPI
from graphene import ObjectType, Int, String, List, Schema, Field, Mutation, Argument, InputObjectType
from fastapi_gql import GQL

users_data = []
posts_data = []
next_user_id = 1
next_post_id = 1

class User(ObjectType):
    id = Int()
    name = String()
    email = String()

class PostInput(InputObjectType):
    title = String(required=True)
    authorId = Int(required=True)

class Post(ObjectType):
    id = Int()
    title = String()
    authorId = Int()

class CreateUser(Mutation):
    class Arguments:
        name = String(required=True)
        email = String(required=True)
    Output = User

    def mutate(self, info, name, email):
        global next_user_id
        user = {'id': next_user_id, 'name': name, 'email': email}
        users_data.append(user)
        next_user_id += 1
        return User(**user)

class CreatePost(Mutation):
    class Arguments:
        input = PostInput(required=True)
    Output = Post

    def mutate(self, info, input):
        global next_post_id
        post = {'id': next_post_id, 'title': input.title, 'authorId': input.authorId}
        posts_data.append(post)
        next_post_id += 1
        return Post(**post)

class Query(ObjectType):
    users = List(User)
    posts = List(Post)

    def resolve_users(self, info):
        return [User(**u) for u in users_data]

    def resolve_posts(self, info):
        return [Post(**p) for p in posts_data]

schema = Schema(query=Query, mutation=[CreateUser, CreatePost])
app = FastAPI()
GQL(app, schema=schema)

