  type Post {
    id: Int
    title: String
    authorId: Int
  }

  type Mutation {
    createPost(title: String!, authorId: Int!): Post
    updatePost(id: Int!, title: String!): Post
    deletePost(id: Int!): Boolean
  }

  type Query {
    posts: [Post]
  }
