from fastapi import FastAPI
from graphene import ObjectType, Int, String, Boolean, List, Schema, Field, Mutation
from fastapi_gql import GQL

posts_data = [
    {'id': 1, 'title': 'Post 1', 'authorId': 1},
    {'id': 2, 'title': 'Post 2', 'authorId': 1}
]
next_id = 3

class Post(ObjectType):
    id = Int()
    title = String()
    authorId = Int()

class CreatePost(Mutation):
    class Arguments:
        title = String(required=True)
        authorId = Int(required=True)
    Output = Post

    def mutate(self, info, title, authorId):
        global next_id
        post = {'id': next_id, 'title': title, 'authorId': authorId}
        posts_data.append(post)
        next_id += 1
        return Post(**post)

class UpdatePost(Mutation):
    class Arguments:
        id = Int(required=True)
        title = String(required=True)
    Output = Post

    def mutate(self, info, id, title):
        for p in posts_data:
            if p['id'] == id:
                p['title'] = title
                return Post(**p)
        return None

class DeletePost(Mutation):
    class Arguments:
        id = Int(required=True)
    Output = Boolean

    def mutate(self, info, id):
        for i, p in enumerate(posts_data):
            if p['id'] == id:
                posts_data.pop(i)
                return True
        return False

class Query(ObjectType):
    posts = List(Post)

    def resolve_posts(self, info):
        return [Post(**p) for p in posts_data]

schema = Schema(query=Query, mutation=[CreatePost, UpdatePost, DeletePost])
app = FastAPI()
GQL(app, schema=schema)

